const std::vector<DialogueLineInfo>& StoryData::GetBranchStory(int roundIndex, int heroineIndex) const
{
    // 회차가 범위를 벗어나면 빈 대사를 반환한다.
    if (roundIndex < 0 || roundIndex >= STORY_ROUND_COUNT)
    {
        return emptyStory;
    }

    // 히로인 번호가 범위를 벗어나면 빈 대사를 반환한다.
    if (heroineIndex < 0 || heroineIndex >= HEROINE_COUNT)
    {
        return emptyStory;
    }

    // 정상 범위라면 해당 회차, 해당 히로인의 스토리를 반환한다.
    return storyScripts[roundIndex][heroineIndex];
}

const std::vector<DialogueLineInfo>& StoryData::GetIntroStory() const
{
    return introStory;
}

const std::vector<DialogueLineInfo>& StoryData::GetFinalChoiceIntroStory(int finalChoiceIndex) const
{
    if (finalChoiceIndex < 0 || finalChoiceIndex >= FINAL_CHOICE_INTRO_COUNT)
    {
        return emptyStory;
    }

    return finalChoiceIntroStories[finalChoiceIndex];
}

const std::vector<DialogueLineInfo>& StoryData::GetEndingStory(int endingType, int heroineIndex) const
{
    if (endingType < 0 || endingType >= ENDING_TYPE_COUNT)
    {
        return emptyStory;
    }

    if (heroineIndex < 0 || heroineIndex >= HEROINE_COUNT)
    {
        return emptyStory;
    }

    return endingStories[endingType][heroineIndex];
}

const std::vector<std::wstring>& StoryData::GetEndingCredits() const
{
    return endingCredits;
}

const std::vector<DialogueLineInfo>& StoryData::GetPerformanceStory(int heroineIndex, bool after) const
{
    if (heroineIndex < 0 || heroineIndex >= HEROINE_COUNT) return emptyStory;
    return after ? performanceOutros[heroineIndex] : performanceIntros[heroineIndex];
}
